struct Evens {
    next: u32,
    end: u32,
}

impl Iterator for Evens {
    type Item = u32;

    fn next(&mut self) -> Option<u32> {
        if self.next > self.end {
            return None;
        }
        let n = self.next;
        self.next += 2;
        Some(n)
    }
}

